{
  "root_cause": "The tablist element lacks role='tablist' and aria-orientation='horizontal', causing the GOVUK Tabs component to interpret vertical arrow keys as navigation between tabs.",
  "repair_strategy": "Add role='tablist' and aria-orientation='horizontal' to the <ul class='govuk-tabs__list'> element.",
  "edits": [
    {
      "path": "index.html",
      "sha256":"24e8e15758ccfc9f3b17cadc01108c076cd71ab50482434408642d3a3ece9dfb",
      "before":"  <ul class=\"govuk-tabs__list\">\n    <li class=\"govuk-tabs__list-item govuk-tabs__list-item--selected\"><a class=\"govuk-tabs__tab\" href=\"#past-day\">Past day</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-week\">Past week</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-month\">Past month</a></li>\n  </ul>",
      "after":"  <ul class=\"govuk-tabs__list\" role=\"tablist\" aria-orientation=\"horizontal\">\n    <li class=\"govuk-tabs__list-item govuk-tabs__list-item--selected\"><a class=\"govuk-tabs__tab\" href=\"#past-day\">Past day</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-week\">Past week</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-month\">Past month</a></li>\n  </ul>"
    }
  ],
  "expected_accessibility_effect": "ArrowDown key press will not move focus away from the active tab; the tab panel remains visible.",
  "functional_risks": [],
  "verification_requirements": [
    "Confirm that ArrowDown does not change focus when a tab is focused.",
    "Confirm that ArrowRight and ArrowLeft move focus to adjacent tabs as expected.",
    "Verify that the tablist is announced with role tablist and orientation horizontal by assistive technology."
  ]
}
